549	// ---------------------------------------------------------------------------
550	// qr_mega (brief-53): single-CTA-per-matrix FUSED panel+trailing MEGAKERNEL.
551	// One CTA owns a WHOLE matrix and runs the ENTIRE blocked Householder QR in ONE
552	// launch (loops all N/BLK outer blocks internally). The panel (and thus V) is
553	// staged in EXPLICIT __shared__ ONCE per block and the WY trailing reads V/T
554	// from smem -- NO Vbuf/Tbuf HBM round-trip, NO L1 re-read of V between the two
555	// WY sweeps (the win the Triton megakernel could not get: Triton owns MMA smem
556	// staging; here we manage smem by hand). grid=(B,), NO grid.sync (single CTA)
557	// -> leaderboard-safe. Header-free (no cuda_fp16.h): plain fp32 scalar math.
558	// Math is the LAPACK dlarfg / dlarft blocked-WY geqrf, bit-compatible with
559	// qr_panel_mcta + _trailing_fused_kernel -> (H,tau) VALID.
560	//
561	// smem layout (mega_smem, unique name): sP (pheight*BLK, column-major V), sT
562	// (BLK*BLK WY T), sred (nwarps), sbc (BLK+2 broadcast), sAt (TH*BNc trailing
563	// tile), sW (BLK*BNc), sYT (BLK*BNc). TH = padded pheight tile height for sAt.
564	// ---------------------------------------------------------------------------
565	extern "C" __global__ void qr_mega(
566	    const float* __restrict__ Ain,   // (B, N, N) row-major (block-0 source)
567	    float* __restrict__ Hout,        // (B, N, N) row-major (factored output, in place after block 0)
568	    float* __restrict__ tauout,      // (B, N)
569	    int B, int N, int BLK, int BNc)
570	{
571	    const int bid = blockIdx.x;
572	    if (bid >= B) return;
573	    const int tid = threadIdx.x;
574	    const int NT  = blockDim.x;
575	    const int lane = tid & 31;
576	    const int warp = tid >> 5;
577	    const int nwarps = (NT + 31) >> 5;
578	
579	    extern __shared__ float mega_smem[];
580	    // sP holds up to N rows x BLK cols (the tallest panel = first block, pheight=N).
581	    float* sP  = mega_smem;                       // N * BLK
582	    float* sT  = sP  + (long)N * BLK;             // BLK * BLK
583	    float* sred = sT + (long)BLK * BLK;           // nwarps (cross-warp reduction)
584	    float* sbc = sred + nwarps;                   // BLK + 2  (tail2, alpha, w[0..BLK-1])
585	    float* sAt = sbc + (BLK + 2);                 // N * BNc  (one trailing tile, loaded per-tile)
586	    float* sW  = sAt + (long)N * BNc;             // BLK * BNc
587	    float* sYT = sW  + (long)BLK * BNc;           // BLK * BNc
588	
589	    const float* Abz = Ain  + (long)bid * N * N;  // block-0 source (A)
590	    float* Hb   = Hout + (long)bid * N * N;       // output / in-place after block 0
591	    float* taub = tauout + (long)bid * N;
592	
593	    // ---- outer blocked loop: factor panel [j:N, j:j+b], apply WY trailing ----
594	    for (int j = 0; j < N; j += BLK) {
595	        int b = BLK; if (j + b > N) b = N - j;
596	        int pheight = N - j;
597	        // block 0 reads A; later blocks read H (panel was written by the prior
598	        // block's trailing). Store base is always H.
599	        const float* srcM = (j == 0) ? Abz : Hb;
600	
601	        // stage panel into sP (column-major): sP[c*pheight + r] = src[(j+r)*N + (j+c)]
602	        for (long idx = tid; idx < (long)pheight * BLK; idx += NT) {
603	            int r = idx % pheight;
604	            int c = idx / pheight;
605	            sP[(long)c * pheight + r] = (c < b) ? srcM[(long)(j + r) * N + (j + c)] : 0.0f;
606	        }
607	        __syncthreads();
608	
609	        // ---- panel factor (single-CTA dlarfg + dlarft, V into sP, T into sT) ----
610	        for (int k = 0; k < b; ++k) {
611	            // tail2 = sum_{r>k} sP[k][r]^2 ; alpha = sP[k][k]
612	            float part = 0.0f;
613	            for (int r = k + 1 + tid; r < pheight; r += NT) {
614	                float x = sP[(long)k * pheight + r];
615	                part += x * x;
616	            }
617	            #pragma unroll
618	            for (int off = 16; off > 0; off >>= 1)
619	                part += __shfl_down_sync(0xffffffffu, part, off);
620	            if (lane == 0) sred[warp] = part;
621	            __syncthreads();
622	            if (tid == 0) {
623	                float s = 0.0f;
624	                for (int w2 = 0; w2 < nwarps; ++w2) s += sred[w2];
625	                sbc[0] = s;
626	                sbc[1] = sP[(long)k * pheight + k];
627	            }
628	            __syncthreads();
629	            float tail2 = sbc[0];
630	            float alpha = sbc[1];
631	
632	            float beta, tau_k, scale;
633	            if (tail2 == 0.0f) { beta = alpha; tau_k = 0.0f; scale = 1.0f; }
634	            else {
635	                float normx = sqrtf(alpha * alpha + tail2);
636	                float sgn = (alpha >= 0.0f) ? 1.0f : -1.0f;
637	                beta = -sgn * normx;
638	                tau_k = (beta - alpha) / beta;
639	                scale = 1.0f / (alpha - beta);
640	            }
641	
642	            // write v into sP col k: v[k]=1 (temp), v[r>k]=col*scale
643	            for (int r = k + 1 + tid; r < pheight; r += NT)
644	                sP[(long)k * pheight + r] *= scale;
645	            if (tid == 0) sP[(long)k * pheight + k] = 1.0f;
646	            __syncthreads();
647	
648	            // w[c] = sum_{r>=k} v_k[r]*sP[c][r] for all c (c<k feeds dlarft, c>k feeds apply)
649	            for (int c = warp; c < b; c += nwarps) {
650	                float acc = 0.0f;
651	                for (int r = k + lane; r < pheight; r += 32)
652	                    acc += sP[(long)k * pheight + r] * sP[(long)c * pheight + r];
653	                #pragma unroll
654	                for (int off = 16; off > 0; off >>= 1)
655	                    acc += __shfl_down_sync(0xffffffffu, acc, off);
656	                if (lane == 0) sbc[2 + c] = acc;
657	            }
658	            __syncthreads();
659	
660	            // in-panel trailing apply (cols c>k): sP[c][r>=k] -= tau_k*v[r]*w[c]
661	            if (tau_k != 0.0f) {
662	                for (int c = k + 1; c < b; ++c) {
663	                    float wc = tau_k * sbc[2 + c];
664	                    for (int r = k + tid; r < pheight; r += NT)
665	                        sP[(long)c * pheight + r] -= sP[(long)k * pheight + r] * wc;
666	                }
667	            }
668	            // dlarft forward: T col k. T[a<k,k] = -tau_k*sum_{c<k} T[a,c]*w[c]; T[k,k]=tau_k.
669	            // sT row-major: sT[a*BLK + c]  (we store T, and read T^T in the trailing).
670	            for (int a = tid; a < BLK; a += NT) {
671	                if (a < k) {
672	                    float s = 0.0f;
673	                    for (int c = 0; c < k; ++c) s += sT[(long)a * BLK + c] * sbc[2 + c];
674	                    sT[(long)a * BLK + k] = -tau_k * s;
675	                } else if (a == k) {
676	                    sT[(long)a * BLK + k] = tau_k;
677	                } else {
678	                    sT[(long)a * BLK + k] = 0.0f;
679	                }
680	            }
681	            // finalize diagonal: sP[k][k] = beta (R), tau
682	            __syncthreads();
683	            if (tid == 0) { sP[(long)k * pheight + k] = (tail2 == 0.0f) ? alpha : beta; taub[j + k] = tau_k; }
684	            __syncthreads();
685	        }
686	
687	        // write the factored panel back to H: Hb[(j+r)*N + (j+c)] = sP[c][r], c<b
688	        for (long idx = tid; idx < (long)pheight * BLK; idx += NT) {
689	            int r = idx % pheight;
690	            int c = idx / pheight;
691	            if (c < b) Hb[(long)(j + r) * N + (j + c)] = sP[(long)c * pheight + r];
692	        }
693	        __syncthreads();
694	
695	        // ---- WY trailing: A_trail[r, cc] -= V @ (T^T @ (V^T @ A_trail)) ----
696	        // V is resident in sP (unit-diag convention: V[k][r] = 1 if r==k, sP[k][r]
697	        // if r>k, else 0). Iterate trailing column tiles of width BNc. A2 staged in
698	        // sAt ONCE per tile -> read once, subtract in place, write once.
699	        int jb = j + b;                 // first trailing column (absolute)
700	        int ncols = N - jb;
701	        for (int c0 = 0; c0 < ncols; c0 += BNc) {
702	            int bw = BNc; if (c0 + bw > ncols) bw = ncols - c0;
703	            // stage A_tile into sAt (row-major within tile). Block 0 reads the SOURCE A
704	            // (the trailing cols are not yet in H); later blocks read H (in place).
705	            for (long idx = tid; idx < (long)pheight * BNc; idx += NT) {
706	                int r  = idx / BNc;
707	                int cc = idx - r * BNc;
708	                sAt[idx] = (cc < bw) ? srcM[(long)(j + r) * N + (jb + c0 + cc)] : 0.0f;
709	            }
710	            __syncthreads();
711	            // sweep 1: W[k][cc] = sum_{r>=k} V[k][r] * sAt[r][cc]   (one warp per k)
712	            for (int k = warp; k < b; k += nwarps) {
713	                for (int cc = 0; cc < BNc; ++cc) {
714	                    float acc = 0.0f;
715	                    // V[k][r]=1 at r==k, sP[k][r] at r>k
716	                    for (int r = k + lane; r < pheight; r += 32) {
717	                        float vkr = (r == k) ? 1.0f : sP[(long)k * pheight + r];
718	                        acc += vkr * sAt[(long)r * BNc + cc];
719	                    }
720	                    #pragma unroll
721	                    for (int off = 16; off > 0; off >>= 1)
722	                        acc += __shfl_down_sync(0xffffffffu, acc, off);
723	                    if (lane == 0) sW[(long)k * BNc + cc] = acc;
724	                }
725	            }
726	            __syncthreads();
727	            // YT = T^T @ W : sYT[k][cc] = sum_{a} T[a][k] * W[a][cc]  (T^T[k][a]=T[a][k])
728	            for (long idx = tid; idx < (long)b * BNc; idx += NT) {
729	                int k  = idx / BNc;
730	                int cc = idx - k * BNc;
731	                float s = 0.0f;
732	                for (int a = 0; a < b; ++a) s += sT[(long)a * BLK + k] * sW[(long)a * BNc + cc];
733	                sYT[(long)k * BNc + cc] = s;
734	            }
735	            __syncthreads();
736	            // sweep 2: sAt[r][cc] -= sum_k V[k][r] * YT[k][cc]; write back once
737	            for (long idx = tid; idx < (long)pheight * BNc; idx += NT) {
738	                int r  = idx / BNc;
739	                int cc = idx - r * BNc;
740	                if (cc < bw) {
741	                    float d = 0.0f;
742	                    for (int k = 0; k < b; ++k) {
743	                        float vkr = (r == k) ? 1.0f : ((r > k) ? sP[(long)k * pheight + r] : 0.0f);
744	                        d += vkr * sYT[(long)k * BNc + cc];
745	                    }
746	                    Hb[(long)(j + r) * N + (jb + c0 + cc)] = sAt[idx] - d;
747	                }
748	            }
749	            __syncthreads();
750	        }
751	    }
752	}
