// ---------------------------------------------------------------------------
// qr_mega (brief-53): single-CTA-per-matrix FUSED panel+trailing MEGAKERNEL.
// One CTA owns a WHOLE matrix and runs the ENTIRE blocked Householder QR in ONE
// launch (loops all N/BLK outer blocks internally). The panel (and thus V) is
// staged in EXPLICIT __shared__ ONCE per block and the WY trailing reads V/T
// from smem -- NO Vbuf/Tbuf HBM round-trip, NO L1 re-read of V between the two
// WY sweeps (the win the Triton megakernel could not get: Triton owns MMA smem
// staging; here we manage smem by hand). grid=(B,), NO grid.sync (single CTA)
// -> leaderboard-safe. Header-free (no cuda_fp16.h): plain fp32 scalar math.
// Math is the LAPACK dlarfg / dlarft blocked-WY geqrf, bit-compatible with
// qr_panel_mcta + _trailing_fused_kernel -> (H,tau) VALID.
//
// smem layout (mega_smem, unique name): sP (pheight*BLK, column-major V), sT
// (BLK*BLK WY T), sred (nwarps), sbc (BLK+2 broadcast), sAt (TH*BNc trailing
// tile), sW (BLK*BNc), sYT (BLK*BNc). TH = padded pheight tile height for sAt.
// ---------------------------------------------------------------------------
extern "C" __global__ void qr_mega(
    const float* __restrict__ Ain,   // (B, N, N) row-major (block-0 source)
    float* __restrict__ Hout,        // (B, N, N) row-major (factored output, in place after block 0)
    float* __restrict__ tauout,      // (B, N)
    int B, int N, int BLK, int BNc)
{
    const int bid = blockIdx.x;
    if (bid >= B) return;
    const int tid = threadIdx.x;
    const int NT  = blockDim.x;
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int nwarps = (NT + 31) >> 5;

    extern __shared__ float mega_smem[];
    // sP holds up to N rows x BLK cols (the tallest panel = first block, pheight=N).
    float* sP  = mega_smem;                       // N * BLK
    float* sT  = sP  + (long)N * BLK;             // BLK * BLK
    float* sred = sT + (long)BLK * BLK;           // nwarps (cross-warp reduction)
    float* sbc = sred + nwarps;                   // BLK + 2  (tail2, alpha, w[0..BLK-1])
    float* sAt = sbc + (BLK + 2);                 // N * BNc  (one trailing tile, loaded per-tile)
    float* sW  = sAt + (long)N * BNc;             // BLK * BNc
    float* sYT = sW  + (long)BLK * BNc;           // BLK * BNc

    const float* Abz = Ain  + (long)bid * N * N;  // block-0 source (A)
    float* Hb   = Hout + (long)bid * N * N;       // output / in-place after block 0
    float* taub = tauout + (long)bid * N;

    // ---- outer blocked loop: factor panel [j:N, j:j+b], apply WY trailing ----
    for (int j = 0; j < N; j += BLK) {
        int b = BLK; if (j + b > N) b = N - j;
        int pheight = N - j;
        // block 0 reads A; later blocks read H (panel was written by the prior
        // block's trailing). Store base is always H.
        const float* srcM = (j == 0) ? Abz : Hb;

        // stage panel into sP (column-major): sP[c*pheight + r] = src[(j+r)*N + (j+c)]
        for (long idx = tid; idx < (long)pheight * BLK; idx += NT) {
            int r = idx % pheight;
            int c = idx / pheight;
            sP[(long)c * pheight + r] = (c < b) ? srcM[(long)(j + r) * N + (j + c)] : 0.0f;
        }
        __syncthreads();

        // ---- panel factor (single-CTA dlarfg + dlarft, V into sP, T into sT) ----
        for (int k = 0; k < b; ++k) {
            // tail2 = sum_{r>k} sP[k][r]^2 ; alpha = sP[k][k]
            float part = 0.0f;
            for (int r = k + 1 + tid; r < pheight; r += NT) {
                float x = sP[(long)k * pheight + r];
                part += x * x;
            }
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1)
                part += __shfl_down_sync(0xffffffffu, part, off);
            if (lane == 0) sred[warp] = part;
            __syncthreads();
            if (tid == 0) {
                float s = 0.0f;
                for (int w2 = 0; w2 < nwarps; ++w2) s += sred[w2];
                sbc[0] = s;
                sbc[1] = sP[(long)k * pheight + k];
            }
            __syncthreads();
            float tail2 = sbc[0];
            float alpha = sbc[1];

            float beta, tau_k, scale;
            if (tail2 == 0.0f) { beta = alpha; tau_k = 0.0f; scale = 1.0f; }
            else {
                float normx = sqrtf(alpha * alpha + tail2);
                float sgn = (alpha >= 0.0f) ? 1.0f : -1.0f;
                beta = -sgn * normx;
                tau_k = (beta - alpha) / beta;
                scale = 1.0f / (alpha - beta);
            }

            // write v into sP col k: v[k]=1 (temp), v[r>k]=col*scale
            for (int r = k + 1 + tid; r < pheight; r += NT)
                sP[(long)k * pheight + r] *= scale;
            if (tid == 0) sP[(long)k * pheight + k] = 1.0f;
            __syncthreads();

            // w[c] = sum_{r>=k} v_k[r]*sP[c][r] for all c (c<k feeds dlarft, c>k feeds apply)
            for (int c = warp; c < b; c += nwarps) {
                float acc = 0.0f;
                for (int r = k + lane; r < pheight; r += 32)
                    acc += sP[(long)k * pheight + r] * sP[(long)c * pheight + r];
                #pragma unroll
                for (int off = 16; off > 0; off >>= 1)
                    acc += __shfl_down_sync(0xffffffffu, acc, off);
                if (lane == 0) sbc[2 + c] = acc;
            }
            __syncthreads();

            // in-panel trailing apply (cols c>k): sP[c][r>=k] -= tau_k*v[r]*w[c]
            if (tau_k != 0.0f) {
                for (int c = k + 1; c < b; ++c) {
                    float wc = tau_k * sbc[2 + c];
                    for (int r = k + tid; r < pheight; r += NT)
                        sP[(long)c * pheight + r] -= sP[(long)k * pheight + r] * wc;
                }
            }
            // dlarft forward: T col k. T[a<k,k] = -tau_k*sum_{c<k} T[a,c]*w[c]; T[k,k]=tau_k.
            // sT row-major: sT[a*BLK + c]  (we store T, and read T^T in the trailing).
            for (int a = tid; a < BLK; a += NT) {
                if (a < k) {
                    float s = 0.0f;
                    for (int c = 0; c < k; ++c) s += sT[(long)a * BLK + c] * sbc[2 + c];
                    sT[(long)a * BLK + k] = -tau_k * s;
                } else if (a == k) {
                    sT[(long)a * BLK + k] = tau_k;
                } else {
                    sT[(long)a * BLK + k] = 0.0f;
                }
            }
            // finalize diagonal: sP[k][k] = beta (R), tau
            __syncthreads();
            if (tid == 0) { sP[(long)k * pheight + k] = (tail2 == 0.0f) ? alpha : beta; taub[j + k] = tau_k; }
            __syncthreads();
        }

        // write the factored panel back to H: Hb[(j+r)*N + (j+c)] = sP[c][r], c<b
        for (long idx = tid; idx < (long)pheight * BLK; idx += NT) {
            int r = idx % pheight;
            int c = idx / pheight;
            if (c < b) Hb[(long)(j + r) * N + (j + c)] = sP[(long)c * pheight + r];
        }
        __syncthreads();

        // ---- WY trailing: A_trail[r, cc] -= V @ (T^T @ (V^T @ A_trail)) ----
        // V is resident in sP (unit-diag convention: V[k][r] = 1 if r==k, sP[k][r]
        // if r>k, else 0). Iterate trailing column tiles of width BNc. A2 staged in
        // sAt ONCE per tile -> read once, subtract in place, write once.
        int jb = j + b;                 // first trailing column (absolute)
        int ncols = N - jb;
        for (int c0 = 0; c0 < ncols; c0 += BNc) {
            int bw = BNc; if (c0 + bw > ncols) bw = ncols - c0;
            // stage A_tile into sAt (row-major within tile). Block 0 reads the SOURCE A
            // (the trailing cols are not yet in H); later blocks read H (in place).
            for (long idx = tid; idx < (long)pheight * BNc; idx += NT) {
                int r  = idx / BNc;
                int cc = idx - r * BNc;
                sAt[idx] = (cc < bw) ? srcM[(long)(j + r) * N + (jb + c0 + cc)] : 0.0f;
            }
            __syncthreads();
            // sweep 1: W[k][cc] = sum_{r>=k} V[k][r] * sAt[r][cc]   (one warp per k)
            for (int k = warp; k < b; k += nwarps) {
